#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <unistd.h>

#define MR 6
#define NR 16
#define KC 256
#define MC 96
#define NC 1024

typedef float v8 __attribute__((vector_size(32)));
typedef float v8u __attribute__((vector_size(32), aligned(4)));

static void pack_B(const float *B, float *dst, int n, int pc, int kc, int jc, int nc)
{
    for (int js = 0; js < nc; js += NR) {
        int w = nc - js < NR ? nc - js : NR;
        for (int p = 0; p < kc; p++) {
            const float *src = B + (size_t)(pc + p) * n + jc + js;
            int jj = 0;
            for (; jj < w; jj++) dst[jj] = src[jj];
            for (; jj < NR; jj++) dst[jj] = 0.0f;
            dst += NR;
        }
    }
}

static void pack_A(const float *A, float *dst, int n, int ic, int mc, int pc, int kc)
{
    for (int is = 0; is < mc; is += MR) {
        int h = mc - is < MR ? mc - is : MR;
        const float *rows[MR];
        for (int r = 0; r < MR; r++)
            rows[r] = A + (size_t)(ic + is + (r < h ? r : 0)) * n + pc;
        for (int p = 0; p < kc; p++) {
            for (int r = 0; r < MR; r++)
                dst[r] = r < h ? rows[r][p] : 0.0f;
            dst += MR;
        }
    }
}

static inline void kernel(int kc, const float *restrict a, const float *restrict b,
                          float *restrict c, int ldc, int mr, int nr, int first)
{
    v8 c00 = {0}, c01 = {0}, c10 = {0}, c11 = {0}, c20 = {0}, c21 = {0};
    v8 c30 = {0}, c31 = {0}, c40 = {0}, c41 = {0}, c50 = {0}, c51 = {0};

    for (int p = 0; p < kc; p++) {
        v8 b0 = *(const v8 *)(b);
        v8 b1 = *(const v8 *)(b + 8);
        float a0 = a[0], a1 = a[1], a2 = a[2], a3 = a[3], a4 = a[4], a5 = a[5];
        c00 += a0 * b0; c01 += a0 * b1;
        c10 += a1 * b0; c11 += a1 * b1;
        c20 += a2 * b0; c21 += a2 * b1;
        c30 += a3 * b0; c31 += a3 * b1;
        c40 += a4 * b0; c41 += a4 * b1;
        c50 += a5 * b0; c51 += a5 * b1;
        a += MR;
        b += NR;
    }

    if (mr == MR && nr == NR) {
#define ST(r, x0, x1)                                              \
        do {                                                       \
            v8u *q0 = (v8u *)(c + (size_t)(r) * ldc);              \
            v8u *q1 = (v8u *)(c + (size_t)(r) * ldc + 8);          \
            if (first) { *q0 = x0; *q1 = x1; }                     \
            else { *q0 += x0; *q1 += x1; }                         \
        } while (0)
        ST(0, c00, c01); ST(1, c10, c11); ST(2, c20, c21);
        ST(3, c30, c31); ST(4, c40, c41); ST(5, c50, c51);
#undef ST
    } else {
        float t[MR][NR] __attribute__((aligned(32)));
        *(v8 *)&t[0][0] = c00; *(v8 *)&t[0][8] = c01;
        *(v8 *)&t[1][0] = c10; *(v8 *)&t[1][8] = c11;
        *(v8 *)&t[2][0] = c20; *(v8 *)&t[2][8] = c21;
        *(v8 *)&t[3][0] = c30; *(v8 *)&t[3][8] = c31;
        *(v8 *)&t[4][0] = c40; *(v8 *)&t[4][8] = c41;
        *(v8 *)&t[5][0] = c50; *(v8 *)&t[5][8] = c51;
        for (int r = 0; r < mr; r++) {
            float *cr = c + (size_t)r * ldc;
            if (first)
                for (int j = 0; j < nr; j++) cr[j] = t[r][j];
            else
                for (int j = 0; j < nr; j++) cr[j] += t[r][j];
        }
    }
}

typedef struct {
    const float *A, *B;
    float *C;
    int n, r0, r1;
} job_t;

static void compute_rows(const float *A, const float *B, float *C, int n, int r0, int r1)
{
    if (r0 >= r1) return;
    float *bp = NULL, *ap = NULL;
    size_t nc_alloc = (size_t)((n < NC ? n : NC) + NR) * KC;
    if (posix_memalign((void **)&bp, 64, nc_alloc * sizeof(float)) ||
        posix_memalign((void **)&ap, 64, (size_t)(MC + MR) * KC * sizeof(float))) {
        /* fallback: naive */
        free(bp); free(ap);
        for (int i = r0; i < r1; i++) {
            float *ci = C + (size_t)i * n;
            for (int j = 0; j < n; j++) ci[j] = 0.0f;
            for (int k = 0; k < n; k++) {
                float a = A[(size_t)i * n + k];
                const float *bk = B + (size_t)k * n;
                for (int j = 0; j < n; j++) ci[j] += a * bk[j];
            }
        }
        return;
    }

    for (int jc = 0; jc < n; jc += NC) {
        int nc = n - jc < NC ? n - jc : NC;
        for (int pc = 0; pc < n; pc += KC) {
            int kc = n - pc < KC ? n - pc : KC;
            int first = (pc == 0);
            pack_B(B, bp, n, pc, kc, jc, nc);
            for (int ic = r0; ic < r1; ic += MC) {
                int mc = r1 - ic < MC ? r1 - ic : MC;
                pack_A(A, ap, n, ic, mc, pc, kc);
                for (int jr = 0; jr < nc; jr += NR) {
                    int nr = nc - jr < NR ? nc - jr : NR;
                    const float *bpp = bp + (size_t)jr * kc;
                    for (int ir = 0; ir < mc; ir += MR) {
                        int mr = mc - ir < MR ? mc - ir : MR;
                        kernel(kc, ap + (size_t)ir * kc, bpp,
                               C + (size_t)(ic + ir) * n + jc + jr, n, mr, nr, first);
                    }
                }
            }
        }
    }
    free(bp);
    free(ap);
}

static void *worker(void *arg)
{
    job_t *j = (job_t *)arg;
    compute_rows(j->A, j->B, j->C, j->n, j->r0, j->r1);
    return NULL;
}

void matmul(const float *A, const float *B, float *C, int n)
{
    if (n <= 0) return;

    long ncpu = sysconf(_SC_NPROCESSORS_ONLN);
    if (ncpu < 1) ncpu = 1;
    if (ncpu > 64) ncpu = 64;

    int strips = (n + MR - 1) / MR;
    int nt = (int)ncpu;
    if ((double)n * n * n < 2e6) nt = 1;
    if (nt > strips) nt = strips;

    if (nt <= 1) {
        compute_rows(A, B, C, n, 0, n);
        return;
    }

    pthread_t th[64];
    job_t jobs[64];
    int created[64];
    for (int t = 0; t < nt; t++) {
        int s0 = (int)((long)strips * t / nt);
        int s1 = (int)((long)strips * (t + 1) / nt);
        int r0 = s0 * MR, r1 = s1 * MR;
        if (r1 > n) r1 = n;
        if (r0 > n) r0 = n;
        jobs[t] = (job_t){A, B, C, n, r0, r1};
    }
    for (int t = 1; t < nt; t++)
        created[t] = pthread_create(&th[t], NULL, worker, &jobs[t]) == 0;
    worker(&jobs[0]);
    for (int t = 1; t < nt; t++) {
        if (created[t]) pthread_join(th[t], NULL);
        else worker(&jobs[t]);
    }
}
```
